## The Gatekeeper Function

A login function must check several things. Result lets you report failures at every step.

### Validating Both Fields

```xiom
fn validate_login(username: Str, password: Str) -> Result[Str, Str] {
  if string.str_length(username) == 0 {
    return Err("Username cannot be empty");
  }
  if string.str_length(password) == 0 {
    return Err("Password cannot be empty");
  }
  if string.str_length(password) < 6 {
    return Err("Password must be at least 6 characters");
  }
  // Simulate checking credentials
  if username == "admin" && password == "secret123" {
    return Ok("Login successful! Welcome, admin.");
  }
  if username == "alice" && password == "password" {
    return Ok("Login successful! Welcome, alice.");
  }
  return Err("Invalid username or password");
}

fn main() -> Int {
  let r1 = validate_login("admin", "secret123");
  let r2 = validate_login("", "anything");
  let r3 = validate_login("alice", "wrong");
  let r4 = validate_login("bob", "short");

  io.println(r1.unwrap_or("Login failed"));
  io.println(r2.unwrap_or("Login failed"));
  io.println(r3.unwrap_or("Login failed"));
  io.println(r4.unwrap_or("Login failed"));
  return 0;
}
```

### Multiple Validation Layers

```xiom
fn check_password_strength(pw: Str) -> Result[Str, Str] {
  let len = string.str_length(pw);
  if len < 8 { return Err("Password too weak: at least 8 characters required"); }
  let has_upper = false;
  let i = 0;
  while i < len {
    let ch = string.str_slice(pw, i, i + 1);
    if ch == "A" { has_upper = true; }
    if ch == "B" { has_upper = true; }
    if ch == "C" { has_upper = true; }
    i = i + 1;
  }
  if !has_upper { return Err("Password too weak: must contain an uppercase letter"); }
  return Ok(pw);
}

fn full_login(user: Str, pass: Str) -> Result[Str, Str] {
  if string.str_length(user) < 3 {
    return Err("Username must be at least 3 characters");
  }
  let strong_pass = check_password_strength(pass)?;
  return Ok("Welcome, " + user + "!");
}
```

