fn login(username: Str, password: Str) -> Result[Str, Str] {
  if string.str_length(username) == 0 {
    return Err("Username cannot be empty");
  }
  if string.str_length(username) < 3 {
    return Err("Username must be at least 3 characters");
  }
  if string.str_length(password) == 0 {
    return Err("Password cannot be empty");
  }
  if string.str_length(password) < 6 {
    return Err("Password must be at least 6 characters");
  }
  if username == "admin" && password == "admin123" {
    return Ok("Welcome back, Administrator!");
  }
  if username == "user" && password == "pass123" {
    return Ok("Welcome back, User!");
  }
  return Err("Invalid username or password");
}

fn main() -> Int {
  io.println(login("admin", "admin123").unwrap_or("Failed"));
  io.println(login("", "x").unwrap_or("Failed"));
  io.println(login("user", "short").unwrap_or("Failed"));
  io.println(login("hacker", "pass123").unwrap_or("Failed"));
  return 0;
}
